package cn.beita.treehole.controller;
import cn.beita.treehole.common.ApiResponse; import cn.beita.treehole.config.AuthInterceptor; import cn.beita.treehole.mapper.PostMapper; import cn.beita.treehole.model.*; import org.springframework.web.bind.annotation.*; import javax.servlet.http.HttpServletRequest; import java.util.*;
@RestController @RequestMapping("/api/me") public class ProfileController { private final PostMapper mapper; public ProfileController(PostMapper m){mapper=m;} @GetMapping("/posts") public ApiResponse<List<Post>> posts(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,HttpServletRequest r){return ApiResponse.ok(mapper.findMine(user(r).getId(),(page-1)*pageSize,Math.min(50,pageSize)));} @GetMapping("/likes") public ApiResponse<List<Post>> likes(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,HttpServletRequest r){return ApiResponse.ok(mapper.findLiked(user(r).getId(),(page-1)*pageSize,Math.min(50,pageSize)));} private UserAccount user(HttpServletRequest r){return (UserAccount)r.getAttribute(AuthInterceptor.CURRENT_USER);} }
